void XPT2046_task(void)
{
    static uint32_t last_time = 0;
    static uint8_t state = 0;
    uint32_t tick = sc_systick_get();
    if (tick - last_time < 10)
    {
        return;
    }
    last_time = tick;
    int x, y;
    int xmin = 435, xmax = 3918; // 原始数据对角座标
    int ymin = 400, ymax = 3754; // 原始数据对角座标
    sc_gui_t *gui = g_gui;
    if (XPT2046IsPress())
    {
        x = XPT2046ReadY(); // 横屏取反
        y = XPT2046ReadX();
        x = x > xmin ? (x - xmin) * 320 / (xmax - xmin) : 0;
        y = y > ymin ? (y - ymin) * 240 / (ymax - ymin) : 0;
        if (state == 0)
        {
            state = 1;
            sc_event_touch(SC_EVENT_TOUCH_DOWN, x, y);
        }
        else if (gui->last_pos_x != x || gui->last_pos_y != y)
        {
            sc_event_touch(SC_EVENT_TOUCH_MOVE, x, y);
        }
    }
    else
    {
        if (state)
        {
            sc_event_touch(SC_EVENT_TOUCH_UP, gui->last_pos_x, gui->last_pos_y);
        }
        state = 0;
    }
}

void main(void)
{
    LCD_Init();
    XPT2046Init();
    sc_gui_init(lcd_dma_flush, NULL, 0x0000U);
    app_ui_init();
    while (1)
    {
        wdt_clear();
        sc_gui_loop();
        XPT2046_task();
    }
}
